Roth.index_sub_weight_le_index_hasseDeriv.{u_1} {σ : Type u_1} [Fintype σ] {P : MvPolynomial σ ℝ} {k : σ →₀ ℕ}
  (hk : (MvPolynomial.hasseDeriv k) P ≠ 0) (α : σ → ℝ) (r : σ → ℕ) :
  Roth.index P α r - Roth.weight r k ≤ Roth.index ((MvPolynomial.hasseDeriv k) P) α r

Roth.le_index_sum.{u_1, u_2} {σ : Type u_1} [Fintype σ] {ι : Type u_2} {s : Finset ι} {f : ι → MvPolynomial σ ℝ}
  {α : σ → ℝ} {r : σ → ℕ} (hs : ∑ i ∈ s, f i ≠ 0) {c : ℝ} (hf : ∀ i ∈ s, f i ≠ 0 → c ≤ Roth.index (f i) α r) :
  c ≤ Roth.index (∑ i ∈ s, f i) α r

@supDegree_sum_le : ∀ {R : Type u_1} {A : Type u_2} {B : Type u_3} [inst : Semiring R] [inst_1 : SemilatticeSup B]
  [inst_2 : OrderBot B] {D : A → B} {ι : Type u_4} {s : Finset ι} {f : ι → R[A]},
  supDegree D (∑ i ∈ s, f i) ≤ s.sup fun i ↦ supDegree D (f i)

@MvPowerSeries.weightedOrder_le : ∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ)
  {f : MvPowerSeries σ R} {d : σ →₀ ℕ},
  (MvPowerSeries.coeff d) f ≠ 0 → MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)

@MvPowerSeries.le_weightedOrder : ∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ)
  {f : MvPowerSeries σ R} {n : ℕ∞},
  (∀ (d : σ →₀ ℕ), ↑((Finsupp.weight w) d) < n → (MvPowerSeries.coeff d) f = 0) → n ≤ MvPowerSeries.weightedOrder w f

Roth.index_prod.{u_1, u_2} {σ : Type u_1} [Fintype σ] {ι : Type u_2} (s : Finset ι) {f : ι → MvPolynomial σ ℝ}
  (hf : ∀ i ∈ s, f i ≠ 0) (α : σ → ℝ) {r : σ → ℕ} (hr : ∀ (j : σ), 0 < r j) :
  Roth.index (∏ i ∈ s, f i) α r = ∑ i ∈ s, Roth.index (f i) α r

Roth.index_rename.{u_1, u_2} {σ : Type u_1} [Fintype σ] {τ : Type u_2} [Fintype τ] {f : σ → τ}
  (hf : Function.Injective f) (P : MvPolynomial σ ℝ) (α : τ → ℝ) (r : τ → ℕ) :
  Roth.index ((MvPolynomial.rename f) P) α r = Roth.index P (α ∘ f) (r ∘ f)

@support_rename_of_injective : ∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R]
  {p : MvPolynomial σ R} {f : σ → τ} [inst_1 : DecidableEq τ],
  Function.Injective f → ((rename f) p).support = Finset.image (Finsupp.mapDomain f) p.support

@Finsupp.linearCombination_mapDomain : ∀ {α : Type u_1} (R : Type u_2) [inst : Semiring R] {α' : Type u_3}
  {M' : Type u_4} [inst_1 : AddCommMonoid M'] [inst_2 : Module R M'] {v' : α' → M'} (f : α → α') (l : α →₀ R),
  (Finsupp.linearCombination R v') (Finsupp.mapDomain f l) = (Finsupp.linearCombination R (v' ∘ f)) l

@comp_aeval_apply : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]
  [inst_2 : Algebra R S₁] (f : σ → S₁) {B : Type u_4} [inst_3 : CommSemiring B] [inst_4 : Algebra R B] (φ : S₁ →ₐ[R] B)
  (p : MvPolynomial σ R), φ ((aeval f) p) = (aeval fun i ↦ φ (f i)) p

@Roth.aeval_X_eq_rename : ∀ {R : Type u_1} [inst : CommSemiring R] {σ : Type u_2} (i : σ) (f : Polynomial R),
  (Polynomial.aeval (MvPolynomial.X i)) f =
    (MvPolynomial.rename fun x ↦ i) ((MvPolynomial.uniqueAlgEquiv R Unit).symm f)

@Roth.hasseDeriv_rename_mul_aeval.{u_1,
    u_2} : ∀ {τ : Type u_1} {R : Type u_2} [inst : CommSemiring.{u_2} R] (d : Finsupp.{u_1, 0} τ ℕ) (ν : ℕ)
  (U : MvPolynomial.{u_1, u_2} τ R) (V : Polynomial.{u_2} R),
  Eq.{max (u_1 + 1) (u_2 + 1)}
    ((MvPolynomial.hasseDeriv.{u_1, u_2}
        (HAdd.hAdd.{u_1, u_1, u_1} (Finsupp.mapDomain.{u_1, u_1, 0} some.{u_1} d)
          (Finsupp.single.{u_1, 0} none.{u_1} ν)))
      (HMul.hMul.{max u_1 u_2, max u_1 u_2, max u_1 u_2} ((MvPolynomial.rename.{u_1, u_1, u_2} some.{u_1}) U)
        ((Polynomial.aeval.{u_2, max u_1 u_2} (MvPolynomial.X.{u_2, u_1} none.{u_1})) V)))
    (HMul.hMul.{max u_1 u_2, max u_1 u_2, max u_1 u_2}
      ((MvPolynomial.rename.{u_1, u_1, u_2} some.{u_1}) ((MvPolynomial.hasseDeriv.{u_1, u_2} d) U))
      ((Polynomial.aeval.{u_2, max u_1 u_2} (MvPolynomial.X.{u_2, u_1} none.{u_1}))
        ((Polynomial.hasseDeriv.{u_2} ν) V)))

@MvPolynomial.hasseDeriv_mul_of_degreeOf_eq_zero : ∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] {d : σ →₀ ℕ}
  {f g : MvPolynomial σ R},
  (∀ j ∈ d.support, MvPolynomial.degreeOf j f = 0) →
    (MvPolynomial.hasseDeriv d) (f * g) = f * (MvPolynomial.hasseDeriv d) g

@MvPolynomial.factorial_smul_hasseDeriv_single : ∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] (j : σ) (n : ℕ)
  (P : MvPolynomial σ R),
  ↑n.factorial • (MvPolynomial.hasseDeriv (Finsupp.single j n)) P = (⇑(MvPolynomial.pderiv j))^[n] P

Roth.exists_coeffNone_basis_aux✝.{u_1, u_2} {τ : Type u_1} {K : Type u_2} [Field K] {P : MvPolynomial (Option τ) K}
  (hP : P ≠ 0) {n : ℕ} (hP' : P = ∑ ν, MvPolynomial.X none ^ ↑ν * (MvPolynomial.rename some) (Roth.coeffNone P ↑ν)) :
  ∃ l b, 1 ≤ l ∧ l ≤ n + 1 ∧ ∀ (ρ : Fin l) (j : τ), MvPolynomial.degreeOf j ↑(b ρ) ≤ MvPolynomial.degreeOf (some j) P
